// DEV_RIO_103 Content + QA + Approval — 実運用
// DEV_RIO_102のexperiment設計（angle/channel/offer等）を受け取る。未指定時のみデフォルト値を使う。
const i = $input.first().json;
return [{ json: {
  content_id: i.content_id ?? 'ca-note-001',
  media: i.media ?? i.channel ?? 'note',
  theme: i.theme ?? '店舗の固定費/決済手数料の見直し',
  audience: i.audience ?? null,
  angle: i.angle ?? 'AIで店舗の雑務を減らす手順',
  cta: i.cta ?? 'Brainで7日分のテンプレを配布中',
  affiliate: i.affiliate ?? null,
  ad_disclosure: i.ad_disclosure ?? (i.affiliate ? 'PR' : null),
  facts: i.facts ?? [],
  real_experience: i.real_experience ?? null,
  line_user_id: i.line_user_id ?? null
} }];

// コンテンツ下書き生成プロンプト。捏造禁止（note_067インシデントの教訓）を明示的にルール化。
const i = $input.first().json;
const factsText = (i.facts && i.facts.length) ? i.facts.map(f => `- ${f.claim}`).join('\n') : '（参考情報なし）';
const experienceInstruction = i.real_experience
  ? `以下は提供された実際の体験談です。この内容だけを使い、他の体験を創作せず、自然な文章として本文に組み込んでください:\n「${i.real_experience}」`
  : '実体験の提供はありません。実体験が必要な箇所は必ず「【実際の経験に置き換える：...】」というプレースホルダーを残してください（創作しないこと）。';
const prompt = `あなたはSNS/note運用担当のコピーライターです。以下の情報から note本文（要旨）とThreads投稿文を1案ずつ作成してください。

テーマ: ${i.theme}
想定読者: ${i.audience ?? '未指定'}
訴求の切り口: ${i.angle}
媒体: ${i.media}
CTA: ${i.cta}
参考情報:
${factsText}

実体験について: ${experienceInstruction}

絶対厳守のルール:
- 提供されていない一人称の体験談・具体的な会話・エピソードを事実として創作してはならない。
- 断定的な効果・収益の保証表現（"必ず稼げる"等）を書かないこと。
- アフィリエイトやPRの場合は本文に明示のPR表記を含めること（affiliate=${i.affiliate ? 'true' : 'false'}）。
- 医療・法律・税務の専門的助言に見える断定表現をしないこと。

出力は必ず次のJSON形式のみで返してください（説明文・コードブロック記号なし）。
{
  "note_body": "string",
  "threads_post": "string"
}`;
const anthropic_body = {
  model: 'claude-sonnet-4-5',
  max_tokens: 4096,
  messages: [ { role: 'user', content: prompt } ]
};
return [{ json: { ...i, draft_prompt: prompt, anthropic_body } }];

// Anthropicの応答をパース。失敗時は空の安全なプレースホルダーにフォールバック（捏造しない）。
const input = $input.first().json;
const o = $('Build Content Draft Prompt').first().json;
let draft = null;
let draft_error = null;

if (input.error) {
  draft_error = 'anthropic_api_error: ' + JSON.stringify(input.error).slice(0, 300);
} else {
  try {
    const text = input.content && input.content[0] && input.content[0].text;
    if (!text) throw new Error('no text in response');
    const cleaned = text.trim().replace(/^```json\s*/i, '').replace(/```\s*$/, '');
    draft = JSON.parse(cleaned);
  } catch (e) {
    draft_error = 'parse_failed: ' + e.message;
  }
}

const note_body = draft && draft.note_body ? draft.note_body : '【AI下書き生成に失敗。人間による手動執筆が必要】';
const threads_post = draft && draft.threads_post ? draft.threads_post : '【AI下書き生成に失敗。人間による手動執筆が必要】';

return [{ json: {
  content_id: o.content_id,
  media: o.media,
  theme: o.theme,
  note_body,
  threads_post,
  cta: o.cta,
  affiliate: o.affiliate,
  ad_disclosure: o.ad_disclosure,
  line_user_id: o.line_user_id,
  draft_source: draft ? 'anthropic_ai' : 'fallback_placeholder',
  draft_error
} }];

// AI自己レビュー用プロンプト（quality-reviewer.mdのチェック観点に準拠）。
const o = $input.first().json;
const prompt = `あなたはコンプライアンスQA担当です。以下の投稿案を、根拠/誤情報・PR表記・アフィリエイト規約・著作権・金融/税務表現・投稿先規約適合の観点でレビューしてください。

媒体: ${o.media}
アフィリエイトあり: ${o.affiliate ? 'true' : 'false'}
PR表記: ${o.ad_disclosure ?? 'なし'}

【note本文】
${o.note_body}

【Threads投稿文】
${o.threads_post}

出力は必ず次のJSON形式のみで返してください（説明文・コードブロック記号なし）。
{
  "qa_status": "PASS または FIX_REQUIRED または BLOCK",
  "issues": ["string"]
}

判定基準:
- 断定的な収益/効果の保証表現、未確認の実体験の断定、PR表記漏れ、著作権侵害の疑い、法律/医療/税務の専門的助言に見える断定表現があれば FIX_REQUIRED 以上とすること。
- アフィリエイトがあるのにPR表記がない場合は BLOCK とすること。`;
const anthropic_body = {
  model: 'claude-haiku-4-5',
  max_tokens: 1024,
  messages: [ { role: 'user', content: prompt } ]
};
return [{ json: { ...o, qa_prompt: prompt, anthropic_body } }];

// AI QA結果 + 決定論的な最低限チェック(§13/RISK_APPROVAL_POLICY)を統合。より厳しい方の判定を採用（AIがPASSでもルール違反があればBLOCK/FIX側を優先）。
const input = $input.first().json;
const o = $('Build QA Prompt').first().json;

let aiQa = null;
let ai_qa_error = null;
if (input.error) {
  ai_qa_error = 'anthropic_api_error: ' + JSON.stringify(input.error).slice(0, 300);
} else {
  try {
    const text = input.content && input.content[0] && input.content[0].text;
    if (!text) throw new Error('no text in response');
    const cleaned = text.trim().replace(/^```json\s*/i, '').replace(/```\s*$/, '');
    aiQa = JSON.parse(cleaned);
  } catch (e) {
    ai_qa_error = 'parse_failed: ' + e.message;
  }
}

// 決定論的な最低限チェック（AI判定が取得できない場合の最終防波堤としても機能）。
const ruleIssues = [];
if (o.affiliate && !o.ad_disclosure) ruleIssues.push('アフィリ掲載だがPR表記なし');
if (!o.note_body || o.note_body.length < 20) ruleIssues.push('本文が短すぎ/空');
if (!o.cta) ruleIssues.push('CTAなし');
if (/【実際の経験に置き換える/.test(o.note_body) || /【AI下書き生成に失敗/.test(o.note_body)) ruleIssues.push('未確定プレースホルダーが残存（公開前に人間の差し替えが必須）');

let ruleStatus;
if (o.affiliate && !o.ad_disclosure) ruleStatus = 'BLOCK';
else if (ruleIssues.length) ruleStatus = 'FIX_REQUIRED';
else ruleStatus = 'PASS';

const rank = { PASS: 0, FIX_REQUIRED: 1, BLOCK: 2 };
const aiStatus = (aiQa && aiQa.qa_status && rank[aiQa.qa_status] !== undefined) ? aiQa.qa_status : 'FIX_REQUIRED';
const aiIssues = (aiQa && Array.isArray(aiQa.issues)) ? aiQa.issues : (ai_qa_error ? [`AI QA取得失敗: ${ai_qa_error}`] : []);

const qa_status = rank[aiStatus] >= rank[ruleStatus] ? aiStatus : ruleStatus;
const issues = [...new Set([...ruleIssues, ...aiIssues])];
const state = qa_status === 'PASS' ? 'WAITING_APPROVAL' : (qa_status === 'BLOCK' ? 'DEAD_LETTER_QUEUE' : 'FAILED_RETRYABLE');

return [{ json: { ...o, qa_status, issues, state, owner_yes_no: 'PENDING',
  ai_qa_error,
  note: qa_status === 'PASS' ? '人間承認待ち(WAITING_APPROVAL)。公開はしない。' : `修正/停止が必要: ${issues.join(' / ')}` } }];

// LINE通知メッセージを組み立てる。line_user_id未設定の場合は通知先が無いため、後続ノードは失敗するが
// continueOnFail(=true)により無視され、パイプライン自体は止まらない（Anthropicノードと同じ安全設計）。
const o = $input.first().json;
const line_user_id = o.line_user_id ?? null;
const line_message = o.state === 'WAITING_APPROVAL'
  ? `【下書き完成】${o.media}「${o.content_id}」の下書きができました。n8nで内容を確認し、問題なければご自身の操作で投稿してください。(QA: ${o.qa_status})`
  : `【要対応】${o.media}「${o.content_id}」の下書きが${o.qa_status}判定です。issues: ${(o.issues || []).join(' / ')}`;
return [{ json: { ...o, line_user_id, line_message } }];
